var cells = Array.prototype.slice.call(root.querySelectorAll('.t210-monitor-matrix-cell'));
var tk = root.querySelector('.t210-monitor-matrix-tk');
var ticks = 0;
cells.forEach(function(c){ c.addEventListener('animationend', function(){ c.classList.remove('t210-monitor-matrix-fu', 't210-monitor-matrix-fd'); }); });
var st = cells.map(function(c){
  return {
    px: parseFloat(c.getAttribute('data-px')),
    dp: parseInt(c.getAttribute('data-dp'), 10),
    chg: parseFloat(c.getAttribute('data-chg')),
    pxEl: c.querySelector('.t210-monitor-matrix-px'),
    chgEl: c.querySelector('.t210-monitor-matrix-chg'),
    el: c
  };
});
function fmt(v, dp){ return v.toLocaleString('en-US', {minimumFractionDigits: dp, maximumFractionDigits: dp}); }
function p4(v){ var s = String(v); while (s.length < 4) s = '0' + s; return s; }
function tick(){
  var s = st[Math.floor(Math.random() * st.length)];
  var move = s.px * (Math.random() - 0.5) * 0.0022;
  if (Math.abs(move) < s.px * 0.00004) move = s.px * 0.00006 * (Math.random() < 0.5 ? -1 : 1);
  s.px += move;
  s.chg += (move / s.px) * 100;
  var up = move > 0;
  s.pxEl.textContent = fmt(s.px, s.dp);
  s.chgEl.textContent = (s.chg >= 0 ? '▲ ' : '▼ ') + Math.abs(s.chg).toFixed(2);
  s.chgEl.className = 't210-monitor-matrix-chg ' + (s.chg >= 0 ? 't210-monitor-matrix-up' : 't210-monitor-matrix-dn');
  if (!reduce) {
    s.el.classList.remove('t210-monitor-matrix-fu', 't210-monitor-matrix-fd');
    void s.el.offsetWidth;
    s.el.classList.add(up ? 't210-monitor-matrix-fu' : 't210-monitor-matrix-fd');
  }
  ticks++;
  tk.textContent = 'TICKS ' + p4(ticks);
}
if (!reduce) setInterval(tick, 620);

