.t210-launchpad{--t210-launchpad-amb:#FFB000;--t210-launchpad-dim:#8E6A18;--t210-launchpad-rule:#332916;--t210-launchpad-grn:#2BE06B;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace;background:#000;border:1px solid var(--t210-launchpad-rule);border-radius:0;color:var(--t210-launchpad-amb);box-sizing:border-box;width:100%;font-variant-numeric:tabular-nums}
.t210-launchpad-hdr{display:flex;align-items:center;justify-content:space-between;padding:3px 6px;border-bottom:1px solid var(--t210-launchpad-rule);font-size:8px;letter-spacing:.12em;box-sizing:border-box}
.t210-launchpad-tag{background:var(--t210-launchpad-amb);color:#000;padding:1px 4px;font-weight:700}
.t210-launchpad-ct{color:var(--t210-launchpad-dim);font-variant-numeric:tabular-nums}
.t210-launchpad-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--t210-launchpad-rule)}
.t210-launchpad-tile{position:relative;overflow:hidden;font-family:inherit;-webkit-appearance:none;appearance:none;background:#000;border:0;border-radius:0;margin:0;padding:4px 5px 5px;display:flex;flex-direction:column;align-items:flex-start;justify-content:space-between;gap:3px;height:44px;cursor:pointer;color:var(--t210-launchpad-amb);text-align:left;transition:background .14s linear}
.t210-launchpad-tile:hover{background:#181104}
.t210-launchpad-tile:focus-visible{outline:1px solid var(--t210-launchpad-grn);outline-offset:-2px}
.t210-launchpad-mn{font-size:11px;font-weight:700;letter-spacing:.03em}
.t210-launchpad-bars{display:flex;align-items:flex-end;gap:2px;height:12px}
.t210-launchpad-b{width:3px;background:#7A5A12;transition:height .45s cubic-bezier(.34,1.56,.64,1),background .2s linear}
.t210-launchpad-tile:hover .t210-launchpad-b{background:var(--t210-launchpad-amb)}
.t210-launchpad-live{background:#241A05;box-shadow:inset 0 0 0 1px var(--t210-launchpad-amb)}
.t210-launchpad-live .t210-launchpad-b{background:var(--t210-launchpad-grn)}
.t210-launchpad-fire::after{content:"";position:absolute;top:0;bottom:0;width:34%;background:linear-gradient(90deg,rgba(255,176,0,0),rgba(255,176,0,.55),rgba(255,176,0,0));animation:t210-launchpad-sweep .55s ease-out 1}
.t210-launchpad-bar{display:flex;align-items:center;gap:5px;padding:4px 6px;border-top:1px solid var(--t210-launchpad-rule);font-size:8px;letter-spacing:.1em;box-sizing:border-box}
.t210-launchpad-crt{color:var(--t210-launchpad-grn)}
.t210-launchpad-st{flex:1;color:var(--t210-launchpad-amb);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.t210-launchpad-pg{width:46px;height:4px;background:#241C0B;flex:none;overflow:hidden}
.t210-launchpad-pgf{display:block;height:4px;width:0;background:var(--t210-launchpad-grn);transition:width .8s linear}
@keyframes t210-launchpad-sweep{from{transform:translateX(-120%)}to{transform:translateX(360%)}}
@media (prefers-reduced-motion:reduce){.t210-launchpad-b{transition:none}.t210-launchpad-fire::after{animation:none;display:none}.t210-launchpad-pgf{transition:none}}

js:
var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var tiles = Array.prototype.slice.call(root.querySelectorAll('.t210-launchpad-tile'));
var st = root.querySelector('.t210-launchpad-st');
var pgf = root.querySelector('.t210-launchpad-pgf');
var typer = null;
function type(text){
  if (reduce) { st.textContent = text; return; }
  clearInterval(typer);
  var i = 0; st.textContent = '';
  typer = setInterval(function(){ i++; st.textContent = text.slice(0, i); if (i >= text.length) clearInterval(typer); }, 20);
}
function launch(t){
  tiles.forEach(function(o){ o.classList.remove('t210-launchpad-live'); o.setAttribute('aria-pressed', 'false'); });
  t.classList.add('t210-launchpad-live');
  t.setAttribute('aria-pressed', 'true');
  if (!reduce) {
    t.classList.remove('t210-launchpad-fire');
    void t.offsetWidth;
    t.classList.add('t210-launchpad-fire');
    setTimeout(function(){ t.classList.remove('t210-launchpad-fire'); }, 600);
  }
  Array.prototype.slice.call(t.querySelectorAll('.t210-launchpad-b')).forEach(function(b, i){
    setTimeout(function(){ b.style.height = (4 + Math.round(Math.random() * 8)) + 'px'; }, reduce ? 0 : i * 55);
  });
  var mn = t.querySelector('.t210-launchpad-mn').textContent;
  type(mn + ' <GO> ' + (t.getAttribute('data-nm') || ''));
  pgf.style.transition = 'none';
  pgf.style.width = '0';
  requestAnimationFrame(function(){
    pgf.style.transition = reduce ? 'none' : 'width .85s linear';
    pgf.style.width = '100%';
  });
}
tiles.forEach(function(t){
  t.setAttribute('aria-pressed', 'false');
  t.addEventListener('click', function(){ launch(t); });
});
